[TestMethod]
public void CalculateTotal_ReturnsCorrectAmount()
{
    var processor = new OrderProcessor(_db, _email, _inventory);
    const decimal sku1UnitPrice = 74.50m;
    const int sku1Qty = 3;
    const decimal sku2UnitPrice = 24.00m;
    const int sku2Qty = 1;
    const decimal taxRate = 0.09m;
    decimal expectedSubtotal = (sku1UnitPrice * sku1Qty) + (sku2UnitPrice * sku2Qty); // 247.50
    decimal expectedTax = Math.Round(expectedSubtotal * taxRate, 2);                  // 22.28
    decimal expectedGrand = expectedSubtotal + expectedTax;                           // 269.78

    var order = new Order { Items = { new OrderItem("SKU-1", sku1Qty), new OrderItem("SKU-2", sku2Qty) } };
    processor.CalculateTotal(order);

    Assert.AreEqual(expectedSubtotal, order.TotalAmount);
    Assert.AreEqual(expectedTax, order.TaxAmount);
    Assert.AreEqual(expectedGrand, order.GrandTotal);
}
```

